def _cmp_pre(a, b):
    # Return -1, 0, 1 comparing pre-release identifier lists.
    # Empty list means no pre-release -> higher precedence.
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1
    for x, y in zip(a, b):
        xnum = x.isdigit()
        ynum = y.isdigit()
        if xnum and ynum:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif xnum and not ynum:
            return -1
        elif ynum and not xnum:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def _cmp(a, b):
    na, pa = a
    nb, pb = b
    if na != nb:
        return -1 if na < nb else 1
    return _cmp_pre(pa, pb)


def sort_versions(vs):
    import functools
    parsed = [(_parse(v), i, v) for i, v in enumerate(vs)]

    def cmp(x, y):
        c = _cmp(x[0], y[0])
        if c != 0:
            return c
        return -1 if x[1] < y[1] else (1 if x[1] > y[1] else 0)

    parsed.sort(key=functools.cmp_to_key(cmp))
    return [p[2] for p in parsed]
